from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    p = Path(path)
    text = p.read_text(encoding='utf-8')
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{path}: expected one match, found {count}')
    p.write_text(text.replace(old, new, 1), encoding='utf-8')


# 1. Adapter registry: retain the existing direct V1-compatible path, but add a
# deadline-bound isolated callback path for V2 callers that explicitly supply a
# monotonic deadline and live authority predicate.
replace_once(
    'aura_ephemeral_adapter_registry.py',
    '''import hashlib\nimport inspect\nimport json\nfrom collections.abc import Callable, Mapping\n''',
    '''import hashlib\nimport inspect\nimport json\nimport multiprocessing\nimport os\nimport signal\nimport time\nfrom collections.abc import Callable, Mapping\n''',
)

replace_once(
    'aura_ephemeral_adapter_registry.py',
    '''def _strict_mapping(value: Any, name: str) -> dict[str, Any]:\n    if type(value) is not dict:\n        raise ValueError(f"{name} must be an exact object")\n    if any(type(key) is not str for key in value):\n        raise ValueError(f"{name} keys must be strings")\n    # Round trip once so caller-owned nested containers cannot mutate the record.\n    try:\n        return json.loads(_canonical_json(value))\n    except json.JSONDecodeError as exc:  # pragma: no cover - canonical output is valid\n        raise ValueError(f"{name} is invalid") from exc\n\n\n@dataclass\n''',
    '''def _strict_mapping(value: Any, name: str) -> dict[str, Any]:\n    if type(value) is not dict:\n        raise ValueError(f"{name} must be an exact object")\n    if any(type(key) is not str for key in value):\n        raise ValueError(f"{name} keys must be strings")\n    # Round trip once so caller-owned nested containers cannot mutate the record.\n    try:\n        return json.loads(_canonical_json(value))\n    except json.JSONDecodeError as exc:  # pragma: no cover - canonical output is valid\n        raise ValueError(f"{name} is invalid") from exc\n\n\ndef _bounded_callback_worker(\n    implementation: Callable[..., dict[str, Any]],\n    params: dict[str, Any],\n    connection: Any,\n    max_output_bytes: int,\n) -> None:\n    \"\"\"Run one already-registered callback inside an isolated POSIX process group.\"\"\"\n    try:\n        os.setsid()\n        connection.send_bytes(b'{"kind":"ready"}')\n        if connection.recv_bytes() != b'execute':\n            return\n        try:\n            result = implementation(**params)\n        except BaseException as exc:\n            if isinstance(exc, Exception):\n                envelope = {\n                    "kind": "callback_error",\n                    "error_type": type(exc).__name__,\n                    "error": str(exc)[:2048],\n                }\n            else:\n                envelope = {\n                    "kind": "base_exception",\n                    "error_type": type(exc).__name__,\n                    "error": str(exc)[:2048],\n                }\n        else:\n            if not isinstance(result, Mapping):\n                envelope = {"kind": "result_error", "error": "adapter_result_must_be_mapping"}\n            else:\n                try:\n                    detached = dict(result)\n                    result_json = _canonical_json(detached)\n                except Exception as exc:\n                    envelope = {\n                        "kind": "result_error",\n                        "error": f"adapter_result_not_canonical: {type(exc).__name__}: {str(exc)[:1024]}",\n                    }\n                else:\n                    encoded = result_json.encode("utf-8")\n                    if len(encoded) > max_output_bytes:\n                        envelope = {\n                            "kind": "result_error",\n                            "error": "adapter_result_transport_limit_exceeded",\n                            "failure_class": "budget",\n                        }\n                    else:\n                        envelope = {"kind": "result", "result_json": result_json}\n        connection.send_bytes(_canonical_json(envelope).encode("utf-8"))\n        # Keep the process-group leader alive until the parent tears the whole\n        # group down. This prevents descendants from surviving a successful\n        # callback return or racing PID/process-group reuse.\n        try:\n            connection.recv_bytes()\n        except EOFError:\n            pass\n    except BaseException:\n        # The parent treats an exited worker without a valid envelope as an\n        # environment failure and still kills/reaps the process group.\n        pass\n    finally:\n        connection.close()\n\n\ndef _kill_bounded_process_group(process: Any) -> None:\n    pid = process.pid\n    if pid is not None and os.name == "posix":\n        try:\n            os.killpg(pid, signal.SIGKILL)\n        except ProcessLookupError:\n            pass\n        except OSError:\n            if process.is_alive():\n                process.kill()\n    elif process.is_alive():\n        process.kill()\n    process.join(timeout=1.0)\n    if process.is_alive():\n        process.kill()\n        process.join(timeout=1.0)\n\n\ndef _execute_bounded_callback(\n    implementation: Callable[..., dict[str, Any]],\n    *,\n    params: dict[str, Any],\n    deadline_monotonic: float,\n    authority_check: Callable[[], bool],\n    max_output_bytes: int,\n) -> dict[str, Any]:\n    \"\"\"Execute one exact callback under a hard parent-owned deadline.\"\"\"\n    if os.name != "posix" or "fork" not in multiprocessing.get_all_start_methods():\n        return {\n            "ok": False,\n            "error": "bounded_adapter_execution_unavailable_on_host",\n            "failure_class": "environment",\n        }\n    if type(deadline_monotonic) not in {int, float} or not float(deadline_monotonic) == float(deadline_monotonic):\n        raise ValueError("deadline_monotonic must be a finite number")\n    if deadline_monotonic in {float("inf"), float("-inf")} or deadline_monotonic <= 0:\n        raise ValueError("deadline_monotonic must be a finite positive number")\n    if type(max_output_bytes) is not int or type(max_output_bytes) is bool or max_output_bytes < 1:\n        raise ValueError("max_output_bytes must be a positive integer")\n    if not callable(authority_check):\n        raise ValueError("authority_check must be callable")\n\n    try:\n        if authority_check() is not True:\n            return {\n                "ok": False,\n                "error": "execution_authority_revoked",\n                "failure_class": "cancellation",\n            }\n    except Exception as exc:\n        return {\n            "ok": False,\n            "error": f"execution_authority_check_failed: {type(exc).__name__}: {exc}",\n            "failure_class": "environment",\n        }\n    if time.monotonic() >= deadline_monotonic:\n        return {"ok": False, "error": "adapter_deadline_exceeded", "failure_class": "budget"}\n\n    context = multiprocessing.get_context("fork")\n    parent, child = context.Pipe(duplex=True)\n    process = context.Process(\n        target=_bounded_callback_worker,\n        args=(implementation, params, child, max_output_bytes),\n        daemon=False,\n    )\n    process.start()\n    child.close()\n    ready = False\n    try:\n        while True:\n            try:\n                authority_active = authority_check() is True\n            except Exception as exc:\n                return {\n                    "ok": False,\n                    "error": f"execution_authority_check_failed: {type(exc).__name__}: {exc}",\n                    "failure_class": "environment",\n                }\n            if not authority_active:\n                return {\n                    "ok": False,\n                    "error": "execution_authority_revoked",\n                    "failure_class": "cancellation",\n                }\n            remaining = deadline_monotonic - time.monotonic()\n            if remaining <= 0:\n                return {\n                    "ok": False,\n                    "error": "adapter_deadline_exceeded",\n                    "failure_class": "budget",\n                }\n            if parent.poll(min(0.01, remaining)):\n                try:\n                    envelope = json.loads(parent.recv_bytes().decode("utf-8"))\n                except (EOFError, UnicodeDecodeError, json.JSONDecodeError):\n                    return {\n                        "ok": False,\n                        "error": "bounded_adapter_protocol_failure",\n                        "failure_class": "environment",\n                    }\n                kind = envelope.get("kind")\n                if kind == "ready" and not ready:\n                    ready = True\n                    # Re-check immediately before granting the one-shot execute token.\n                    try:\n                        if authority_check() is not True or time.monotonic() >= deadline_monotonic:\n                            continue\n                    except Exception as exc:\n                        return {\n                            "ok": False,\n                            "error": f"execution_authority_check_failed: {type(exc).__name__}: {exc}",\n                            "failure_class": "environment",\n                        }\n                    parent.send_bytes(b"execute")\n                    continue\n                if kind == "result" and ready:\n                    # Authority/deadline are checked again *after* callback completion\n                    # and before accepting any output from the child.\n                    try:\n                        if authority_check() is not True:\n                            return {\n                                "ok": False,\n                                "error": "execution_authority_revoked",\n                                "failure_class": "cancellation",\n                            }\n                    except Exception as exc:\n                        return {\n                            "ok": False,\n                            "error": f"execution_authority_check_failed: {type(exc).__name__}: {exc}",\n                            "failure_class": "environment",\n                        }\n                    if time.monotonic() >= deadline_monotonic:\n                        return {\n                            "ok": False,\n                            "error": "adapter_deadline_exceeded",\n                            "failure_class": "budget",\n                        }\n                    try:\n                        decoded = json.loads(envelope["result_json"])\n                    except (KeyError, TypeError, json.JSONDecodeError):\n                        return {\n                            "ok": False,\n                            "error": "bounded_adapter_result_decode_failed",\n                            "failure_class": "structural",\n                        }\n                    return decoded\n                if kind == "callback_error":\n                    return {\n                        "ok": False,\n                        "error": f"adapter_callback_failed: {envelope.get('error_type', 'Exception')}: {envelope.get('error', '')}",\n                        "failure_class": "environment",\n                    }\n                if kind == "result_error":\n                    return {\n                        "ok": False,\n                        "error": envelope.get("error", "adapter_result_invalid"),\n                        "failure_class": envelope.get("failure_class", "structural"),\n                    }\n                if kind == "base_exception":\n                    error_type = envelope.get("error_type", "BaseException")\n                    message = envelope.get("error", "")\n                    if error_type == "KeyboardInterrupt":\n                        raise KeyboardInterrupt(message)\n                    if error_type == "SystemExit":\n                        raise SystemExit(message)\n                    if error_type == "GeneratorExit":\n                        raise GeneratorExit(message)\n                    raise BaseException(f"adapter process interruption: {error_type}: {message}")\n                return {\n                    "ok": False,\n                    "error": "bounded_adapter_protocol_failure",\n                    "failure_class": "environment",\n                }\n            if not process.is_alive():\n                return {\n                    "ok": False,\n                    "error": "bounded_adapter_worker_exited_without_result",\n                    "failure_class": "environment",\n                }\n    finally:\n        _kill_bounded_process_group(process)\n        parent.close()\n\n\n@dataclass\n''',
)

old_execute = '''    def execute(self, adapter_id: str, *, params: dict[str, Any] | None = None,\n                lease_active: bool = True) -> dict[str, Any]:\n        try:\n            params = {} if params is None else _strict_mapping(params, "params")\n        except ValueError as exc:\n            return {"ok": False, "error": f"invalid_adapter_params: {exc}",\n                    "failure_class": "structural",\n                    "patch_authority": PATCH_AUTHORITY,\n                    "vsa_patch_authority": VSA_PATCH_AUTHORITY}\n        meta = self._adapters.get(adapter_id)\n        if not meta:\n            return {"ok": False, "error": f"unknown_adapter: {adapter_id}", "status": "DENIED",\n                    "patch_authority": PATCH_AUTHORITY, "vsa_patch_authority": VSA_PATCH_AUTHORITY}\n        if meta.revocation_state == "REVOKED" or meta.operational_status == "DENIED":\n            return {"ok": False, "error": f"adapter_revoked: {adapter_id}", "status": "DENIED",\n                    "patch_authority": PATCH_AUTHORITY, "vsa_patch_authority": VSA_PATCH_AUTHORITY}\n        if meta.operational_status != "OPERATIONAL":\n            return {"ok": False, "error": f"adapter_not_operational: {adapter_id} ({meta.operational_status})",\n                    "status": meta.operational_status,\n                    "patch_authority": PATCH_AUTHORITY, "vsa_patch_authority": VSA_PATCH_AUTHORITY}\n        if lease_active is not True:\n            return {"ok": False, "error": "lease_revoked: adapter calls blocked",\n                    "patch_authority": PATCH_AUTHORITY, "vsa_patch_authority": VSA_PATCH_AUTHORITY}\n        impl = self._implementations.get(adapter_id)\n        if impl is None:\n            return {"ok": False, "error": f"no_implementation: {adapter_id}", "status": "NOT_OPERATIONAL",\n                    "patch_authority": PATCH_AUTHORITY, "vsa_patch_authority": VSA_PATCH_AUTHORITY}\n        try:\n            result = impl(**params)\n        except Exception as exc:\n            return {"ok": False, "error": f"adapter_callback_failed: {type(exc).__name__}: {exc}",\n                    "adapter": adapter_id, "failure_class": "environment",\n                    "adapter_digest": meta.adapter_digest,\n                    "implementation_digest": meta.implementation_digest,\n                    "patch_authority": PATCH_AUTHORITY, "vsa_patch_authority": VSA_PATCH_AUTHORITY}\n        if not isinstance(result, Mapping):\n            return {"ok": False, "error": "adapter_result_must_be_mapping", "adapter": adapter_id,\n                    "failure_class": "structural",\n                    "patch_authority": PATCH_AUTHORITY, "vsa_patch_authority": VSA_PATCH_AUTHORITY}\n        detached = dict(result)\n        if type(detached.get("ok")) is not bool:\n            return {"ok": False, "error": "adapter_result_missing_status", "adapter": adapter_id,\n                    "failure_class": "structural",\n                    "adapter_digest": meta.adapter_digest,\n                    "implementation_digest": meta.implementation_digest,\n                    "patch_authority": PATCH_AUTHORITY, "vsa_patch_authority": VSA_PATCH_AUTHORITY}\n        detached["adapter"] = adapter_id\n        detached["operational_status"] = "OPERATIONAL"\n        detached["adapter_digest"] = meta.adapter_digest\n        detached["implementation_digest"] = meta.implementation_digest\n        detached["patch_authority"] = PATCH_AUTHORITY\n        detached["vsa_patch_authority"] = VSA_PATCH_AUTHORITY\n        return detached\n'''

new_execute = '''    def execute(\n        self,\n        adapter_id: str,\n        *,\n        params: dict[str, Any] | None = None,\n        lease_active: bool = True,\n        deadline_monotonic: float | None = None,\n        authority_check: Callable[[], bool] | None = None,\n        max_output_bytes: int = 4_000_000,\n    ) -> dict[str, Any]:\n        try:\n            params = {} if params is None else _strict_mapping(params, "params")\n        except ValueError as exc:\n            return {"ok": False, "error": f"invalid_adapter_params: {exc}",\n                    "failure_class": "structural",\n                    "patch_authority": PATCH_AUTHORITY,\n                    "vsa_patch_authority": VSA_PATCH_AUTHORITY}\n        meta = self._adapters.get(adapter_id)\n        if not meta:\n            return {"ok": False, "error": f"unknown_adapter: {adapter_id}", "status": "DENIED",\n                    "patch_authority": PATCH_AUTHORITY, "vsa_patch_authority": VSA_PATCH_AUTHORITY}\n        if meta.revocation_state == "REVOKED" or meta.operational_status == "DENIED":\n            return {"ok": False, "error": f"adapter_revoked: {adapter_id}", "status": "DENIED",\n                    "patch_authority": PATCH_AUTHORITY, "vsa_patch_authority": VSA_PATCH_AUTHORITY}\n        if meta.operational_status != "OPERATIONAL":\n            return {"ok": False, "error": f"adapter_not_operational: {adapter_id} ({meta.operational_status})",\n                    "status": meta.operational_status,\n                    "patch_authority": PATCH_AUTHORITY, "vsa_patch_authority": VSA_PATCH_AUTHORITY}\n        if lease_active is not True:\n            return {"ok": False, "error": "lease_revoked: adapter calls blocked",\n                    "patch_authority": PATCH_AUTHORITY, "vsa_patch_authority": VSA_PATCH_AUTHORITY}\n        impl = self._implementations.get(adapter_id)\n        if impl is None:\n            return {"ok": False, "error": f"no_implementation: {adapter_id}", "status": "NOT_OPERATIONAL",\n                    "patch_authority": PATCH_AUTHORITY, "vsa_patch_authority": VSA_PATCH_AUTHORITY}\n        if deadline_monotonic is None:\n            # Compatibility path: callers that do not opt into the V2 bounded\n            # execution contract retain the historical in-process behavior.\n            try:\n                result = impl(**params)\n            except Exception as exc:\n                return {"ok": False, "error": f"adapter_callback_failed: {type(exc).__name__}: {exc}",\n                        "adapter": adapter_id, "failure_class": "environment",\n                        "adapter_digest": meta.adapter_digest,\n                        "implementation_digest": meta.implementation_digest,\n                        "patch_authority": PATCH_AUTHORITY, "vsa_patch_authority": VSA_PATCH_AUTHORITY}\n        else:\n            if authority_check is None:\n                raise ValueError("authority_check is required for bounded adapter execution")\n            result = _execute_bounded_callback(\n                impl,\n                params=params,\n                deadline_monotonic=deadline_monotonic,\n                authority_check=authority_check,\n                max_output_bytes=max_output_bytes,\n            )\n        if not isinstance(result, Mapping):\n            return {"ok": False, "error": "adapter_result_must_be_mapping", "adapter": adapter_id,\n                    "failure_class": "structural",\n                    "patch_authority": PATCH_AUTHORITY, "vsa_patch_authority": VSA_PATCH_AUTHORITY}\n        detached = dict(result)\n        if type(detached.get("ok")) is not bool:\n            return {"ok": False, "error": "adapter_result_missing_status", "adapter": adapter_id,\n                    "failure_class": "structural",\n                    "adapter_digest": meta.adapter_digest,\n                    "implementation_digest": meta.implementation_digest,\n                    "patch_authority": PATCH_AUTHORITY, "vsa_patch_authority": VSA_PATCH_AUTHORITY}\n        detached["adapter"] = adapter_id\n        detached["operational_status"] = "OPERATIONAL"\n        detached["adapter_digest"] = meta.adapter_digest\n        detached["implementation_digest"] = meta.implementation_digest\n        detached["patch_authority"] = PATCH_AUTHORITY\n        detached["vsa_patch_authority"] = VSA_PATCH_AUTHORITY\n        return detached\n'''
replace_once('aura_ephemeral_adapter_registry.py', old_execute, new_execute)

# 2. Runtime: start cumulative wall-time authority at activation and enforce the
# minimum of node timeout, workspace wall budget, and absolute TTL during the
# callback itself.
replace_once(
    'aura_ephemeral_workspace_runtime_v2.py',
    '''        store.update_workspace_v2(workspace_id, sandbox_path=sandbox["temp_dir"])\n        moved = store.transition_workspace_v2(workspace_id, "ACTIVATING", "ACTIVE")\n''',
    '''        activation_record = _workspace(store, workspace_id)\n        activation_usage = dict(activation_record["usage_json"])\n        # Runtime wall-time authority begins when the admitted workspace becomes\n        # executable, not at recipe compilation/admission or caller-supplied time.\n        activation_usage["started_at"] = time.time()\n        store.update_workspace_v2(\n            workspace_id, sandbox_path=sandbox["temp_dir"], usage_json=activation_usage,\n        )\n        moved = store.transition_workspace_v2(workspace_id, "ACTIVATING", "ACTIVE")\n''',
)

replace_once(
    'aura_ephemeral_workspace_runtime_v2.py',
    '''    started = _trusted_now(now)\n    upstream_digests = [receipts[parent]["receipt_digest"] for parent in sorted(parents[node_key])]\n    try:\n        raw = adapter_registry.execute(\n            node["adapter_id"], params=clean_params,\n            lease_active=store.is_workspace_v2_lease_active(workspace_id, now=started),\n        )\n        output = _detach_json(raw, name="adapter_result")\n''',
    '''    started = _trusted_now(now)\n    authority_started = time.time()\n    workspace_started = _finite(expected_usage.get("started_at"), "workspace usage started_at")\n    workspace_deadline = workspace_started + graph["budgets"]["wall_time_ms"] / 1000.0\n    if authority_started >= workspace_deadline:\n        return _fail_workspace_v2(\n            workspace_id, store=store, failure_class="budget",\n            reason="workspace wall-time budget exhausted", node_id=node_key,\n        )\n    absolute_deadlines = {\n        "node": authority_started + node["timeout_ms"] / 1000.0,\n        "workspace": workspace_deadline,\n        "ttl": record["expires_at"],\n    }\n    deadline_kind, absolute_deadline = min(absolute_deadlines.items(), key=lambda item: item[1])\n    deadline_monotonic = time.monotonic() + max(0.0, absolute_deadline - authority_started)\n\n    def execution_authority_active() -> bool:\n        if not store.is_workspace_v2_lease_active(workspace_id):\n            return False\n        binding = adapter_registry.get_binding(node["adapter_id"])\n        current = binding.get("binding", {})\n        return bool(\n            binding.get("ok")\n            and adapter_registry.is_operational(node["adapter_id"])\n            and current.get("adapter_digest") == node["adapter_digest"]\n            and current.get("implementation_digest") == node["implementation_digest"]\n        )\n\n    def invalidated_execution_result() -> dict[str, Any]:\n        current = _workspace(store, workspace_id)\n        if current["state"] == "DISSOLVED":\n            return {\n                "ok": False, "error": "workspace_execution_invalidated",\n                "workspace_id": workspace_id, "node_id": node_key,\n                "state": "DISSOLVED", "receipt_committed": False,\n            }\n        current_binding = adapter_registry.get_binding(node["adapter_id"])\n        binding_body = current_binding.get("binding", {})\n        if (\n            not current_binding.get("ok")\n            or not adapter_registry.is_operational(node["adapter_id"])\n            or binding_body.get("adapter_digest") != node["adapter_digest"]\n            or binding_body.get("implementation_digest") != node["implementation_digest"]\n        ):\n            return _fail_workspace_v2(\n                workspace_id, store=store, failure_class="stale",\n                reason="adapter binding invalidated during execution", node_id=node_key,\n            )\n        return {\n            "ok": False, "error": "workspace_execution_invalidated",\n            "workspace_id": workspace_id, "node_id": node_key,\n            "state": current["state"], "receipt_committed": False,\n        }\n\n    def expired_execution_result() -> dict[str, Any]:\n        try:\n            _expire_if_needed(workspace_id, store=store)\n        except ValueError:\n            pass\n        final = _workspace(store, workspace_id)\n        failure = final["failure_records"][-1] if final["failure_records"] else {}\n        return {\n            "ok": False, "error": "workspace_execution_expired",\n            "workspace_id": workspace_id, "node_id": node_key,\n            "failure": failure, "cleanup": final.get("cleanup_receipt", {}),\n            "state": final["state"], "receipt_committed": False,\n        }\n\n    upstream_digests = [receipts[parent]["receipt_digest"] for parent in sorted(parents[node_key])]\n    try:\n        raw = adapter_registry.execute(\n            node["adapter_id"], params=clean_params,\n            lease_active=store.is_workspace_v2_lease_active(workspace_id),\n            deadline_monotonic=deadline_monotonic,\n            authority_check=execution_authority_active,\n            max_output_bytes=min(\n                graph["budgets"]["output_bytes"], MAX_OUTPUT_BYTES\n            ),\n        )\n        output = _detach_json(raw, name="adapter_result")\n        if output.get("error") == "execution_authority_revoked":\n            current = _workspace(store, workspace_id)\n            if current["state"] != "DISSOLVED" and time.time() >= current["expires_at"]:\n                return expired_execution_result()\n            return invalidated_execution_result()\n        if output.get("error") == "adapter_deadline_exceeded":\n            current = _workspace(store, workspace_id)\n            if current["state"] != "DISSOLVED" and time.time() >= current["expires_at"]:\n                return expired_execution_result()\n            return _fail_workspace_v2(\n                workspace_id, store=store, failure_class="budget",\n                reason=f"{deadline_kind} execution deadline exceeded", node_id=node_key,\n            )\n        if output.get("error", "").startswith("execution_authority_check_failed"):\n            return _fail_workspace_v2(\n                workspace_id, store=store, failure_class="environment",\n                reason=output["error"], node_id=node_key,\n            )\n        completed_real = time.time()\n        current = _workspace(store, workspace_id)\n        if current["state"] != "DISSOLVED" and completed_real >= current["expires_at"]:\n            return expired_execution_result()\n        if not execution_authority_active():\n            return invalidated_execution_result()\n        if time.monotonic() >= deadline_monotonic:\n            return _fail_workspace_v2(\n                workspace_id, store=store, failure_class="budget",\n                reason=f"{deadline_kind} execution deadline exceeded", node_id=node_key,\n            )\n''',
)

